'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',accounts:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',bulb:'M9 18h6 M10 22h4 M8 14a7 7 0 1 1 8 0c-1.5 1-1 3-1 4H9c0-1 .5-3-1-4',research:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',pen:'M12 20h9 M16.5 3.5a2 2 0 0 1 3 3L8 18l-4 1 1-4z',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h6',layout:'M3 3h18v18H3z M3 9h18 M9 9v12',calendar:'M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2',chart:'M3 3v18h18 M7 16v-5 M12 16V7 M17 16v-9',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',skill:'M12 3l9 5-9 5-9-5z M3 12l9 5 9-5 M3 16l9 5 9-5',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M13 6l6 6-6 6',check:'M5 12l4 4L19 6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',download:'M12 3v12 M6 9l6 6 6-6 M4 16v5h16v-5',menu:'M4 6h16 M4 12h16 M4 18h16',moon:'M21 12.8A9 9 0 0 1 11.2 3 9 9 0 1 0 21 12.8',shield:'M12 2l9 4v6c0 6-9 10-9 10S3 18 3 12V6z M8 12l3 3 5-6',external:'M15 3h6v6 M10 14L21 3 M21 14v5a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5'};
const ico=k=>`<svg class="ico" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[k]||icons.file}"/></svg>`;
const btn=(label,act,extra='',cls='')=>`<button class="${cls}" data-act="${act}" ${extra}>${label}</button>`;
const tag=(label,cls='')=>`<span class="tag ${cls}">${esc(label)}</span>`;
const navs=[['overview','grid','运营总览'],['accounts','accounts','账号矩阵'],['topics','bulb','选题研究'],['benchmarks','research','对标研究'],['studio','pen','AI 创作'],['library','file','内容中心'],['layout','layout','排版中心'],['publishing','calendar','发布中心'],['analytics','chart','数据中心'],['ai','spark','模型配置'],['skills','skill','Skill 中心']];
const statusName={idea:'灵感收集',research:'研究中',ready:'待创作',done:'已完成',review:'待审核',approved:'审核通过',manual_pending:'待人工发布',published:'已发布',cancelled:'已取消',draft:'草稿',running:'运行中',succeeded:'候选已生成',failed:'失败',interrupted:'已中断'};
const state={accounts:[],accountId:localStorage.getItem('ms-account')||'',page:'overview',view:'board',filter:'',studio:null,dirty:false,saving:null,saveError:null,timer:null,skills:[],providers:[],runs:[],month:new Date(),publishView:'calendar',overviewAll:false,libraryDeleted:false};
const act={},dataId=e=>e.dataset.id,acc=()=>state.accounts.find(a=>a.id===state.accountId),platform=p=>p==='xhs'?'小红书':'微信公众号',fmt=(s,short=false)=>s?new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',...(short?{}:{hour:'2-digit',minute:'2-digit'}),hour12:false}).format(new Date(s)):'—';
async function api(path,opts={}){const r=await fetch('/api/'+path,{...opts,headers:{'content-type':'application/json',...opts.headers},body:opts.body===undefined?undefined:JSON.stringify(opts.body)});const d=await r.json();if(!r.ok)throw Object.assign(new Error(d.error||'请求失败'),{status:r.status});return d}
const scope=()=>'?accountId='+encodeURIComponent(state.accountId),records=(kind)=>api('records/'+kind+(state.accountId?scope():''));
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),5000)}
function empty(title,detail,action='',label='立即添加',icon='file',compact=false){return `<div class="empty ${compact?'compact':''}"><div class="empty-icon">${ico(icon)}</div><h3>${esc(title)}</h3><div>${esc(detail)}</div>${action?btn(label,action,'','small'):''}</div>`}
function title(name,desc,action='',label=''){return `<div class="page-heading"><div><div class="eyebrow">YOUR CREATIVE OPERATING SYSTEM</div><h1>${name}</h1><p>${esc(desc)}</p></div>${action?btn(ico('plus')+' '+label,action,'','primary'):''}</div>`}
function field(name,label,value='',type='text',hint='',wide=false){return `<div class="field ${wide?'wide':''}"><label for="f-${name}">${esc(label)}</label>${type==='textarea'?`<textarea id="f-${name}" name="${name}" rows="4">${esc(value)}</textarea>`:`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="any"':''}>`}${hint?`<p class="field-hint">${esc(hint)}</p>`:''}</div>`}
function select(name,label,value,options,hint=''){return `<div class="field"><label for="f-${name}">${esc(label)}</label><select id="f-${name}" name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select>${hint?`<p class="field-hint">${esc(hint)}</p>`:''}</div>`}
function modal(name,html,submit,wide=false){const d=$('#modal'),generation=crypto.randomUUID();d.dataset.generation=generation;d.innerHTML=`<div class="modal-head"><h2>${esc(name)}</h2>${btn('×','close','','ghost')}</div><form id="modal-form"><div class="modal-body">${html}<div class="modal-error" id="modal-error"></div><div class="modal-actions">${btn('取消','close','type="button"')}${submit?'<button class="primary" type="submit">保存</button>':''}</div></div></form>`;d.style.width=wide?'min(940px, calc(100% - 28px))':'';if(!d.open)d.showModal();d.scrollTop=0;if(submit)$('#modal-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('[type=submit]');button.disabled=true;$('#modal-error').textContent='';try{await submit(Object.fromEntries(new FormData(form)),form);if(d.dataset.generation===generation)d.close()}catch(err){$('#modal-error').textContent=err.message;button.disabled=false}}}
async function refreshAccounts(){state.accounts=await api('accounts');if(!acc())state.accountId=state.accounts[0]?.id||'';localStorage.setItem('ms-account',state.accountId)}
function shell(){const n=navs.find(n=>n[0]===state.page);$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark"><i></i><i></i><i></i><i></i></span>Media Studio</div><div class="workspace"><small>当前创作空间</small><select id="account-switch" aria-label="切换当前账号">${state.accounts.length?state.accounts.map(a=>`<option value="${a.id}" ${a.id===state.accountId?'selected':''}>${a.platform==='wechat'?'◉':'▣'} ${esc(a.name)}${a.status==='inactive'?' · 已停用':''}</option>`).join(''):'<option>尚未添加账号</option>'}</select></div><div class="nav-label">WORKSPACE</div><nav class="nav">${navs.map(([key,icon,name])=>`<button data-nav="${key}" class="${state.page===key?'active':''}">${ico(icon)}${name}</button>`).join('')}</nav><div class="sidebar-bottom"><nav class="nav"><button data-nav="settings" class="${state.page==='settings'?'active':''}">${ico('settings')}设置与备份</button></nav><div class="private"><i class="dot"></i>本机工作空间 · 数据独立保存</div></div></aside><main class="main"><header class="topbar"><div class="inline">${btn(ico('menu'),'menu','','mobile-menu ghost')}<span class="breadcrumb">工作空间 <span class="muted">/</span><strong>${n?n[2]:'设置与备份'}</strong></span></div><div class="top-actions">${btn('搜索当前账号内容 <kbd>⌘ K</kbd>','search','','search-trigger')}${btn(ico('moon'),'theme','aria-label="切换深浅主题"','ghost small')}<span class="avatar">我</span></div></header><div class="page" id="page"><div class="empty skeleton">正在载入你的工作空间…</div></div></main></div>`;$('#account-switch').onchange=async e=>{const next=e.target.value;try{await flush();state.accountId=next;state.studio=null;state.runs=[];state.filter='';localStorage.setItem('ms-account',next);toast('已切换账号，选题、素材与 AI 上下文已同步切换');await render()}catch(err){e.target.value=state.accountId;toast(err.message)}}}
async function go(page,contentId){try{await flush();state.page=page;if(contentId)state.openId=contentId;location.hash=page+(contentId?'/'+contentId:'');await render()}catch(e){toast(e.message)}}
let renderToken=0;async function render(){const token=++renderToken;shell();try{if(!state.accountId&&!['accounts','settings','ai','skills','overview'].includes(state.page)){if(token===renderToken)$('#page').innerHTML=title(navs.find(n=>n[0]===state.page)?.[2]||'工作空间','每个账号都有自己的独立内容空间')+empty('先添加你的第一个账号','支持多个公众号、小红书账号；账号之间的内容独立保存。','add-account','添加账号','accounts');return}const html=await pages[state.page]();if(token!==renderToken)return;$('#page').innerHTML=html;bindPage();}catch(e){if(token===renderToken)$('#page').innerHTML=empty('暂时无法载入',e.message,'retry','重试')}}
const pages={};
pages.overview=async()=>{const o=await api('overview'+(!state.overviewAll&&state.accountId?scope():'')),jobs=o.jobs.filter(j=>j.data.status!=='cancelled'),pending=jobs.filter(j=>['review','approved','manual_pending'].includes(j.data.status)),pub=jobs.filter(j=>j.data.status==='published');const latest=latestMetrics(o.metrics),readValues=latest.map(m=>m.data.reads).filter(x=>x!==null&&x!==undefined),total=readValues.length?readValues.reduce((a,b)=>a+b,0).toLocaleString():'—';const stats=[['选题储备',o.topics.length,'个独立选题，等待好内容发生','bulb'],['在创作内容',o.contents.length,'所有已保存的原创稿件','pen'],['待推进发布',pending.length,'审核与人工发布待办','calendar'],['累计阅读',total,readValues.length?'已导入作品最新快照 · 非期间增量':'尚未导入真实运营数据','chart']];const bars=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const key=localDay(d),count=pub.filter(j=>localDay(new Date(j.data.published_at))===key).length;return {label:(d.getMonth()+1)+'.'+d.getDate(),count}});return title('让好内容，有序发生。',new Intl.DateTimeFormat('zh-CN',{dateStyle:'full'}).format(new Date())+' · '+(state.overviewAll?'全账号运营汇总':acc()?.name||'个人工作空间'),'add-content','开始创作')+`<div class="inline" style="margin:-10px 0 20px">${btn('当前账号','overview-current','','small '+(!state.overviewAll?'primary':''))}${btn('全账号汇总','overview-all','','small '+(state.overviewAll?'primary':''))}<span class="caption">${state.overviewAll?'仅汇总运营，不混合创作资料':'仅展示当前账号的选题、稿件和运营数据'}</span></div><div class="hero"><div><h2>灵感有归处，创作有节奏。</h2><p>${state.accounts.length?'从一个选题出发，研究、打磨、排版，再让内容遇见读者。':'欢迎来到你的内容工作室。先添加一个账号，为它建立专属选题池和创作规则。'}</p></div><div class="hero-art"><div class="paper back"></div><div class="paper"></div><span class="spark">✦</span></div></div><div class="stats">${stats.map(([label,val,desc,icon])=>`<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${ico(icon)}</span></div><div class="stat-value">${val}</div><div class="stat-footer">${desc}</div></div>`).join('')}</div><div class="grid-main"><div><section class="panel"><div class="panel-head"><h2>创作动态 <span class="caption"> / 最近 7 天发布量</span></h2>${tag('来自真实发布记录','gray')}</div><div class="chart">${bars.map(b=>`<div class="chart-bar" style="height:${b.count?Math.max(12,b.count/Math.max(1,...bars.map(x=>x.count))*115):2}px"><b>${b.count||''}</b><span>${b.label}</span></div>`).join('')}</div><div class="caption" style="margin-top:17px">${pub.length?'仅统计已回填链接并确认的发布记录':'还没有已确认的发布记录，完成第一次发布后，这里会记录你的节奏。'}</div></section><section class="panel"><div class="panel-head"><h2>近期内容</h2>${btn('查看全部 →','nav-library','','ghost small')}</div>${o.contents.length?o.contents.slice(0,5).map(c=>`<div class="list-row"><span class="stat-icon">${ico('file')}</span><div class="list-main"><h4>${esc(c.data.title)}</h4><p>${esc(o.accounts.find(a=>a.id===c.account_id)?.name||'')} · ${fmt(c.updated_at)}</p></div>${tag('v'+c.revision,'gray')}${btn('继续编辑','open-content',`data-id="${c.id}" data-account="${c.account_id}"`,'small')}</div>`).join(''):empty('还没有内容','把一个想法写下来，就是很好的开始。','add-content','创建第一篇内容','pen',true)}</section></div><div><section class="panel"><div class="panel-head"><h2>接下来要做的事</h2>${tag(pending.length+' 项','gray')}</div>${pending.length?pending.slice(0,4).map(j=>`<div class="list-row"><div class="dateblock">${new Date(j.data.scheduled_at).getMonth()+1}月<b>${new Date(j.data.scheduled_at).getDate()}</b></div><div class="list-main"><h4>${esc(j.data.title)}</h4><p>${statusName[j.data.status]} · ${fmt(j.data.scheduled_at)}</p></div></div>`).join(''):empty('日程留白，灵感先行','在发布中心安排下一篇内容。','nav-publishing','规划发布','calendar',true)}</section><section class="panel"><div class="panel-head"><h2>快捷开始</h2></div><div class="quick-grid">${[['bulb','add-topic','收集选题'],['pen','add-content','新建内容'],['accounts','add-account','添加账号']].map(([i,a,l])=>btn(ico(i)+l,a)).join('')}</div></section><section class="panel"><div class="panel-head"><h2>工作空间状态</h2><i class="dot"></i></div><div class="list-row"><div class="list-main"><h4>${o.accounts.length} 个运营账号</h4><p>账号资料与内容独立归属</p></div>${ico('shield')}</div><div class="list-row"><div class="list-main"><h4>手工发布模式</h4><p>导出内容 → 平台发布 → 回填链接</p></div>${tag('可用','green')}</div><div class="caption" style="line-height:1.8;padding-top:15px">没有真实数据时，阅读量保持为空。每一个数字都可以回溯到你的录入记录。</div></section></div></div><div class="statusbar"><span>Media Studio / 独立创作，持续积累</span><span>数据保存在本机 · 不自动发布</span></div>`};
pages.accounts=async()=>title('每个账号，独立生长。','为不同定位建立独立的选题、对标研究、写作规则和内容资产。','add-account','添加账号')+(state.accounts.length?`<div class="account-grid">${state.accounts.map(a=>`<article class="card"><div class="card-header"><span class="platform-icon ${a.platform==='xhs'?'xhs':''}">${ico(a.platform==='xhs'?'file':'accounts')}</span>${tag(a.status==='active'?'运营中':'已停用',a.status==='active'?'green':'gray')}</div><h3>${esc(a.name)}</h3><span class="caption">${platform(a.platform)}</span><p>${esc(a.data.positioning||'尚未填写账号定位')}</p><div class="inline">${tag('独立选题库')}${tag('人工发布','gray')}</div><div class="card-footer">${btn('进入工作空间 →','select-account',`data-id="${a.id}"`,'ghost small')}${btn('编辑档案','edit-account',`data-id="${a.id}"`,'small')}</div></article>`).join('')}</div>`:empty('从第一个账号开始','你录入的每个账号都会拥有自己的选题、研究和稿件。','add-account','添加账号','accounts'));
pages.topics=async()=>{const items=(await records('topic')).filter(r=>JSON.stringify(r.data).toLowerCase().includes(state.filter.toLowerCase())),statuses=['idea','research','ready','done'];state.items=items;return title('把灵感，变成下一篇。',acc().name+' · 专属选题池，所有研究和引用都归属于这个账号。','add-topic','收集选题')+`<div class="toolbar"><div class="tabs" style="margin:0">${btn('看板','topic-board','',''+(state.view==='board'?'active':''))}${btn('列表','topic-list','',''+(state.view==='list'?'active':''))}</div><div class="filters"><input id="list-search" aria-label="搜索当前账号选题" placeholder="搜索这个账号的选题…" value="${esc(state.filter)}">${tag(items.length+' 个选题','gray')}</div></div>`+(state.view==='board'?`<div class="board">${statuses.map(s=>`<section class="column"><div class="column-title"><span><i class="dot" style="background:${{idea:'#b3a1d8',research:'#d7b17c',ready:'#8caabf',done:'#8bb3a1'}[s]}"></i> ${statusName[s]}</span><span class="caption">${items.filter(t=>(t.data.status||'idea')===s).length}</span></div>${items.filter(t=>(t.data.status||'idea')===s).map(t=>`<article class="card"><div class="inline" style="margin-bottom:10px">${tag(t.data.priority==='high'?'优先创作':'灵感储备',t.data.priority==='high'?'orange':'gray')}</div><h3>${esc(t.data.title)}</h3><p>${esc(t.data.angle||t.data.description||'等待补充创作角度')}</p><div class="card-footer">${btn('编辑','edit-topic',`data-id="${t.id}"`,'ghost small')}${btn('开始创作 ↗','topic-write',`data-id="${t.id}"`,'small')}</div></article>`).join('')}${btn('＋ 收集选题','add-topic',`data-status="${s}"`,'ghost small')}</section>`).join('')}</div>`:`<section class="panel">${items.length?`<div class="table-wrap"><table><thead><tr><th>选题与角度</th><th>状态</th><th>优先级</th><th>操作</th></tr></thead><tbody>${items.map(t=>`<tr><td class="table-title">${esc(t.data.title)}<small>${esc(t.data.angle)}</small></td><td>${tag(statusName[t.data.status]||'灵感收集')}</td><td>${t.data.priority==='high'?'优先':'常规'}</td><td><div class="inline">${btn('编辑','edit-topic',`data-id="${t.id}"`,'small')}${btn('创作','topic-write',`data-id="${t.id}"`,'small')}${btn('复制到账号','clone-topic',`data-id="${t.id}"`,'ghost small')}</div></td></tr>`).join('')}</tbody></table></div>`:empty('选题池等待你的灵感','记录一个观察，或从对标文章中提炼独特角度。','add-topic','收集选题','bulb')}</section>`)};
pages.benchmarks=async()=>{const [bench,posts]=await Promise.all([records('benchmark'),records('post')]);state.benchmarks=bench;state.posts=posts;return title('向优秀学习，写自己的内容。',acc().name+' · 对标关注、文章拆解和研究笔记独立保存。','add-benchmark','添加对标账号')+`<div class="notice">对标对象是公开研究资料。链接与摘要由你录入，不自动抓取原文；未知互动数据保留为空。</div>`+(bench.length?`<div class="cards">${bench.map(b=>`<article class="card"><div class="card-header"><span class="platform-icon ${acc().platform==='xhs'?'xhs':''}">${ico('research')}</span>${tag(b.data.priority==='high'?'重点观察':'持续观察','gray')}</div><h3>${esc(b.data.title)}</h3><p>${esc(b.data.rationale||'尚未填写研究理由')}</p><div class="inline">${b.data.url?`<a href="${esc(b.data.url)}" target="_blank" rel="noopener noreferrer" class="caption">公开主页 ↗</a>`:''}</div><div class="card-footer"><span>${posts.filter(p=>p.data.benchmark_id===b.id).length} 篇研究</span><div class="inline">${btn('编辑','edit-benchmark',`data-id="${b.id}"`,'ghost small')}${btn('研究详情 →','benchmark-detail',`data-id="${b.id}"`,'small')}</div></div></article>`).join('')}</div>`:empty('为这个账号找到学习对象','每个对标对象的研究理由和文章笔记都独立保存。','add-benchmark','添加对标账号','research'))};
pages.library=async()=>{const rows=await api('records/content'+scope()+(state.libraryDeleted?'&deleted=1':''));state.contents=rows;return title('内容，是慢慢积累的资产。',acc().name+' · 主稿、修订和 AI 候选各自保存，可随时回看。','add-content','新建内容')+`<div class="toolbar"><div class="tabs" style="margin:0">${btn('全部稿件','library-active','',''+(!state.libraryDeleted?'active':''))}${btn('回收站','library-trash','',''+(state.libraryDeleted?'active':''))}${btn('素材库','assets','','')}</div><span class="caption">${rows.length} 篇内容</span></div><section class="panel">${rows.length?`<div class="table-wrap"><table><thead><tr><th>标题 / 摘要</th><th>目标平台</th><th>版本</th><th>更新时间</th><th>操作</th></tr></thead><tbody>${rows.map(c=>`<tr><td class="table-title">${esc(c.data.title)}<small>${esc(c.data.summary||c.data.body?.slice(0,45)||'还没有正文')}</small></td><td>${tag(platform(c.data.platform),c.data.platform==='wechat'?'green':'red')}</td><td class="muted">v${c.revision}</td><td class="muted">${fmt(c.updated_at)}</td><td><div class="inline">${state.libraryDeleted?btn('恢复','recover-content',`data-id="${c.id}"`,'small'):btn('继续编辑','open-content',`data-id="${c.id}"`,'small')+btn('排版','layout-content',`data-id="${c.id}"`,'ghost small')+btn('历史','history-content',`data-id="${c.id}"`,'ghost small')+btn('移入回收站','delete-content',`data-id="${c.id}"`,'ghost small')}</div></td></tr>`).join('')}</tbody></table></div>`:empty(state.libraryDeleted?'回收站为空':'好内容从第一稿开始','为当前账号创建一篇稿件，或从选题池进入创作。',state.libraryDeleted?'':'add-content','新建内容','file')}</section>`};
pages.studio=async()=>{[state.skills,state.providers,state.runs]=await Promise.all([records('skill'),records('provider'),api('runs'+scope())]);const contents=await records('content');state.contents=contents;let c;if(state.openId){c=contents.find(c=>c.id===state.openId);state.openId=null}else if(state.studio?.account_id===state.accountId)c=contents.find(c=>c.id===state.studio.id);if(!c)c=contents[0];if(!c){state.studio=null;return title('留一张白纸，给新的想法。',acc().name+' · AI 生成候选，最后一笔由你决定。','add-content','新建内容')+empty('开启你的创作工作室','新建任务默认「AI 直接写作」，所有 Skill 都由你主动选择。','add-content','新建第一篇稿件','pen')}state.studio=c;state.dirty=false;state.saveError=null;if(c.data.writing_skill_version_id&&!state.skills.some(s=>s.data.version_id===c.data.writing_skill_version_id)){try{const old=await api('skill-version/'+c.data.writing_skill_version_id+scope()+'&platform='+c.data.platform+'&type=writing');old.data.title+='（已锁定历史版本）';state.skills.push(old)}catch{}}const d=c.data,wskills=state.skills.filter(s=>s.data.enabled&&s.data.skill_type==='writing'),hskills=state.skills.filter(s=>s.data.enabled&&s.data.skill_type==='humanize'&&(s.data.platform==='all'||s.data.platform===d.platform)),providers=state.providers.filter(p=>p.data.enabled&&p.data.protocol!=='image'),selectedProvider=d.provider_id||'';const runs=state.runs.filter(r=>r.content_id===c.id);return title('写作的专注，留在这里。',acc().name+' · 每次生成都保存为独立候选，不覆盖当前正文。','add-content','新建内容')+`<div class="studio"><section class="panel studio-settings"><div class="panel-head"><h2>本次创作</h2>${ico('settings')}</div>${select('current-content','当前稿件',c.id,contents.map(x=>[x.id,x.data.title]))}${select('studio-provider','AI 模型',selectedProvider,[['','按任务 / 账号 / 全局路由'],...providers.map(p=>[p.id,p.data.title+' / '+p.data.model])],d.provider_id?'任务级选择':acc().data.default_provider_id?'使用账号默认模型':'尚未配置默认模型')}<div class="field"><label>选择写作方式</label><label class="radio-card"><input type="radio" name="writing-mode" value="" ${!d.writing_skill_version_id?'checked':''}><span>AI 直接写作<small>不加载写作 Skill · 新任务默认</small></span></label>${wskills.map(s=>{const match=s.data.platform==='all'||s.data.platform===d.platform;return `<label class="radio-card"><input type="radio" name="writing-mode" value="${s.data.version_id}" ${d.writing_skill_version_id===s.data.version_id?'checked':''} ${!match?'disabled':''}><span>${esc(s.data.title)}<small>v${esc(s.data.version)}${!match?' · 平台不匹配':''}${acc().data.recommended_skill===s.id?' · 账号推荐':''}</small></span></label>`}).join('')}${d.writing_skill_version_id&&!wskills.some(s=>s.data.version_id===d.writing_skill_version_id)?'<div class="notice warning">原 Skill 不可用，请重新选择写作方式。</div>':''}${!wskills.length?'<p class="field-hint">还没有已启用的写作 Skill，可在 Skill 中心导入。</p>':''}</div><div class="field"><label class="inline"><input type="checkbox" id="humanize-enabled" ${d.humanize_enabled?'checked':''}>生成后执行去 AI 味 Skill</label><p class="field-hint">默认关闭 · 两份候选分别保留</p></div>${select('humanize-skill','后处理 Skill',d.humanize_skill_version_id||'',[['','选择后处理 Skill'],...hskills.map(s=>[s.data.version_id,s.data.title+' v'+s.data.version])])}<div class="notice" style="margin-bottom:0">${ico('shield')} 仅引用当前账号选题、关联研究和显式选定素材。</div>${btn('选择引用素材','select-assets','','ghost small')}</section><section class="panel editor-panel"><div class="editor-toolbar"><span>Markdown 编辑器</span><div class="inline">${btn('版本历史','history-current','','ghost small')}${btn('排版预览 ↗','layout-current','','ghost small')}</div></div><input class="editor-title" id="editor-title" aria-label="文章标题" value="${esc(d.title)}" placeholder="给这个想法一个标题"><input class="editor-summary" id="editor-summary" aria-label="文章摘要" value="${esc(d.summary||'')}" placeholder="添加摘要，让思路更清晰…"><textarea class="editor-body" id="editor-body" aria-label="文章正文" placeholder="从这里开始写作。\n\n也可以告诉右侧的 AI 助手你的想法，生成候选初稿。">${esc(d.body||'')}</textarea><div class="editor-footer"><span id="save-status">${ico('check')} 已保存 · v${c.revision}</span>${btn('重试保存','retry-save','','ghost small')}<span id="word-count">${(d.body||'').replace(/\s/g,'').length} 字</span></div></section><section class="panel studio-ai"><div class="panel-head"><h2>${ico('spark')} 创作助手</h2>${tag('独立候选')}</div><div class="field"><label for="ai-instruction">这一次，想怎样表达？</label><textarea id="ai-instruction" rows="4" placeholder="例如：用一个具体问题切入，语气自然，保留事实出处。"></textarea></div><div class="ai-actions">${btn(ico('spark')+' 生成完整初稿','ai-draft','','primary')}${btn('生成大纲','ai-outline')}${btn('多标题建议','ai-titles')}${btn('按要求改写','ai-rewrite')}${btn('后处理正文','ai-humanize')}</div><div id="ai-feedback" class="run-state">${selectedProvider?'调用真实模型，费用按配置价格估算。':'请先在模型配置页添加供应商和 API Key。'}</div><div id="candidates">${runs.length?runs.slice(0,3).map(runCard).join(''):empty('候选会出现在这里','生成后先比较，再决定是否采纳。','','','spark',true)}</div></section></div>`};
function runCard(r){const d=r.data;return `<div style="border-top:1px solid var(--line);padding-top:16px;margin-top:18px"><div class="inline">${tag(statusName[r.status]||r.status,r.status==='failed'?'red':r.status==='succeeded'?'green':'gray')}<span class="caption">${fmt(r.created_at)}</span></div><div class="run-state" style="margin:10px 0">${esc(d.model||'')} · ${d.writing_skill_version_id?'使用 Skill':'直接写作'}${d.humanize_skill_version_id?' + 后处理':''}<br>${d.usage?`${d.usage.input_tokens+d.usage.output_tokens} tokens · `:''}${d.estimated_cost!==undefined?'估算 '+(d.currency||'USD')+' '+Number(d.estimated_cost).toFixed(5):''}${d.partial?'<br>后处理失败，已保留初稿。':''}</div>${d.error?`<div class="notice warning">${esc(d.error)}</div>`:''}${r.status==='running'?btn('取消任务','cancel-run',`data-id="${r.id}"`,'small'):''}${d.output?`<div class="candidate">${esc(d.output)}</div><div class="inline">${btn('比较并采纳','compare-run',`data-id="${r.id}"`,'primary small')}${btn('复制候选','copy-run',`data-id="${r.id}"`,'small')}</div>`:''}</div>`}
function mdHTML(s){let out='',inList=false;for(const line of s.split('\n')){if(/^[-*] /.test(line)){if(!inList){out+='<ul>';inList=true}out+='<li>'+esc(line.slice(2))+'</li>';continue}if(inList){out+='</ul>';inList=false}const v=esc(line).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');if(/^### /.test(line))out+='<h3>'+v.slice(4)+'</h3>';else if(/^## /.test(line))out+='<h2>'+v.slice(3)+'</h2>';else if(/^# /.test(line))out+='<h2>'+v.slice(2)+'</h2>';else if(/^> /.test(line))out+='<blockquote>'+v.slice(5)+'</blockquote>';else if(line.trim())out+='<p>'+v+'</p>'}return out+(inList?'</ul>':'')}
pages.layout=async()=>{const contents=await records('content');state.contents=contents;const c=contents.find(c=>c.id===state.openId||c.id===state.layoutId)||contents[0];state.openId=null;if(!c)return title('让文字，拥有合适的样子。','公众号长文和小红书图文，分别排版和导出。')+empty('先完成一篇稿件','内容保存在内容中心，排版与导出随时可以继续。','add-content','新建内容','layout');state.layoutId=c.id;return title('把内容，打磨到最后一页。',acc().name+' · 导出的是当前保存版本 v'+c.revision)+`<div class="preview-grid"><section class="panel"><div class="panel-head"><h2>排版与导出</h2>${tag(platform(c.data.platform))}</div>${select('layout-content','当前稿件',c.id,contents.map(c=>[c.id,c.data.title]))}<div class="notice">${c.data.platform==='wechat'?'公众号导出包含内联样式的 HTML 和 Markdown，可人工复制到公众号后台。':'小红书按正文分页生成 1080 × 1440 文字卡片，支持 PNG 素材包导出。'}</div><div class="field">${select('layout-style','排版风格',state.layoutStyle||'lavender',[['lavender','浅紫 · 温柔叙事'],['sage','草木 · 读书札记'],['ink','墨色 · 专业表达']])}</div><div class="inline">${btn(ico('download')+' 导出 Markdown','export-md','','primary')}${btn('公众号 HTML','export-html')}${btn('小红书 PNG 素材包','export-cards')}</div><div class="inline" style="margin-top:15px">${btn('回到编辑器','layout-edit')}${btn('创建发布排期','schedule-current','','primary')}${btn('派生另一平台版本','derive-content')}</div><div class="notice warning" style="margin-top:24px">导出前请核查事实、版权、标题长度与平台当前规则。文字卡片不会冒充照片或已制作的封面。</div><div class="caption">当前正文 ${(c.data.body||'').replace(/\s/g,'').length} 字 · 所有 HTML 都进行文本转义 · 内容样式为导出快照</div></section><div><div class="caption" style="text-align:center;margin-bottom:15px">手机阅读预览</div><div class="phone"><div class="phone-top"><span>9:41</span><span>${platform(c.data.platform)}</span></div><article class="phone-content" id="phone-preview" style="--accent:${{lavender:'#7662d7',sage:'#578b74',ink:'#343e4e'}[state.layoutStyle||'lavender']}"><h1>${esc(c.data.title)}</h1><p style="color:#999;font-size:10px">${esc(acc().name)} · v${c.revision}</p>${mdHTML(c.data.body||'正文会出现在这里。')}</article></div></div></div>`};
pages.publishing=async()=>{const [jobs,contents]=await Promise.all([records('job'),records('content')]);state.jobs=jobs;state.contents=contents;const mo=state.month,first=new Date(mo.getFullYear(),mo.getMonth(),1),offset=(first.getDay()+6)%7,start=new Date(first);start.setDate(1-offset);return title('让发布，回到自己的节奏。',acc().name+' · 审核具体版本，人工发布后回填真实链接。','schedule','创建排期')+`<div class="toolbar"><div class="tabs" style="margin:0">${btn('发布日历','publish-calendar','',''+(state.publishView==='calendar'?'active':''))}${btn('发布队列','publish-queue','',''+(state.publishView==='queue'?'active':''))}</div><div class="inline">${btn('‹','month-prev','','small')}<span style="font-size:13px">${mo.getFullYear()} 年 ${mo.getMonth()+1} 月</span>${btn('›','month-next','','small')}</div></div><div class="notice">手工发布流程：创建排期 → 审核当前版本 → 导出并人工发布 → 回填链接。修改已审核稿件后，需要重新审核。</div>`+(state.publishView==='calendar'?`<div class="calendar">${['一','二','三','四','五','六','日'].map(x=>`<div class="day weekday">周${x}</div>`).join('')}${Array.from({length:42},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);const ds=localDay(d);return `<div class="day ${d.getMonth()!==mo.getMonth()?'dim':''} ${ds===localDay(new Date())?'today':''}"><b>${d.getDate()}</b>${jobs.filter(j=>localDay(new Date(j.data.scheduled_at))===ds&&j.data.status!=='cancelled').map(j=>btn(esc(j.data.title),'job-detail',`data-id="${j.id}" title="${esc(statusName[j.data.status])}"`,'cal-job')).join('')}</div>`}).join('')}</div>`:`<section class="panel">${jobs.length?jobs.map(j=>`<div class="list-row"><div class="dateblock">${new Date(j.data.scheduled_at).getMonth()+1}月<b>${new Date(j.data.scheduled_at).getDate()}</b></div><div class="list-main"><h4>${esc(j.data.title)}</h4><p>${fmt(j.data.scheduled_at)} · ${platform(j.data.platform)}</p></div>${tag(statusName[j.data.status]||j.data.status,j.data.status==='published'?'green':j.data.status==='review'?'orange':'gray')}${btn('查看与处理','job-detail',`data-id="${j.id}"`,'small')}</div>`).join(''):empty('还没有发布排期','把准备好的稿件放进日历，按自己的节奏发布。','schedule','创建排期','calendar')}</section>`)};
function latestMetrics(metrics){const map=new Map();metrics.forEach(m=>{const old=map.get(m.data.job_id);if(!old||Date.parse(old.data.observed_at)<Date.parse(m.data.observed_at)||old.data.observed_at===m.data.observed_at&&old.updated_at<m.updated_at)map.set(m.data.job_id,m)});return [...map.values()]}
pages.analytics=async()=>{const [metrics,jobs]=await Promise.all([records('metric'),records('job')]);state.metrics=metrics;state.jobs=jobs;const latest=latestMetrics(metrics),total=k=>{const v=latest.map(m=>m.data[k]).filter(x=>x!==null&&x!==undefined);return v.length?v.reduce((a,b)=>a+b,0).toLocaleString():'—'};return title('用真实反馈，校准下一次创作。',acc().name+' · 每篇作品只采用最新累计快照，空值与零分别处理。','add-metric','录入真实指标')+`<div class="stats">${[['累计阅读','reads'],['累计点赞','likes'],['累计收藏','saves'],['累计评论','comments']].map(([l,k])=>`<div class="stat"><div class="stat-top">${l}${ico('chart')}</div><div class="stat-value">${total(k)}</div><div class="stat-footer">${latest.length?'已录入作品最新累计快照':'尚未导入 · 缺失不填零'}</div></div>`).join('')}</div><div class="toolbar"><span class="caption">${metrics.length} 条采集记录 · ${latest.length} 篇有指标的作品</span><div class="inline">${btn('CSV 格式说明','csv-template','','small')}${btn('导入 CSV','import-metrics','','small')}</div></div><section class="panel">${latest.length?`<div class="table-wrap"><table><thead><tr><th>作品 / 数据来源</th><th>阅读</th><th>点赞</th><th>收藏</th><th>评论</th><th>采集时间</th></tr></thead><tbody>${latest.map(m=>`<tr><td class="table-title">${esc(jobs.find(j=>j.id===m.data.job_id)?.data.title||m.data.job_id)}<small>${m.data.source==='csv'?'CSV 导入':'人工录入'} · ${esc(m.data.note||'')}</small></td>${['reads','likes','saves','comments'].map(k=>`<td>${m.data[k]??'—'}</td>`).join('')}<td class="muted">${fmt(m.data.observed_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('还没有可分析的真实数据','先在发布中心确认一篇已发布作品，再录入或导入它的实际指标。','','','chart')}</section><div class="notice">指标口径：累计快照只取每篇作品的最新采集值，不把历史快照相加；汇总仅用于当前账号，不跨平台合并互动率。${latest.length?'当前仅覆盖已录入的作品。':''}</div>`};
pages.ai=async()=>{const ps=await records('provider');state.providers=ps;return title('模型由你配置，创作由你掌控。','支持 OpenAI 兼容协议与 Anthropic 协议；模型 ID、价格和预算都可配置。','add-provider','添加模型配置')+`<div class="notice">API Key 只在本机服务端加密保存，界面仅返回掩码。连接测试会真实调用供应商接口，可能产生少量费用。</div>`+(ps.length?`<div class="cards">${ps.map(p=>`<article class="card"><div class="card-header"><span class="stat-icon">${ico('spark')}</span>${tag(p.data.enabled?'已启用':'已停用',p.data.enabled?'green':'gray')}</div><h3>${esc(p.data.title)}</h3><p>${esc(p.data.model)}<br>${esc(p.data.base_url)}</p><div class="inline">${tag(p.data.protocol,'gray')}${tag((p.data.currency||'USD')+' '+p.data.per_run_limit+' / 次','gray')}</div><div class="card-footer"><div class="inline">${btn('连接测试','test-provider',`data-id="${p.id}"`,'small')}${btn('模型目录','model-catalog',`data-id="${p.id}"`,'ghost small')}</div>${btn('配置','edit-provider',`data-id="${p.id}"`,'small')}</div></article>`).join('')}</div>`:empty('连接你常用的 AI 模型','填写 Base URL、模型 ID 和 API Key，测试连接后即可开始真实写作。','add-provider','配置第一个模型','spark'))+`<section class="panel" style="margin-top:25px"><div class="panel-head"><h2>当前账号模型路由</h2>${tag('任务选择 > 账号默认','gray')}</div>${acc()?`${select('default-provider','账号默认模型',acc().data.default_provider_id||'',[['','未配置'],...ps.filter(p=>p.data.enabled).map(p=>[p.id,p.data.title+' / '+p.data.model])])}${btn('保存账号默认','save-default-provider','','primary small')}`:'<p class="subtitle">添加账号后可为其配置独立的默认模型。</p>'}<p class="field-hint">更换模型不会改变新任务的写作方式。新任务始终默认 AI 直接写作。</p></section>`};
pages.skills=async()=>{state.skills=await records('skill');return title('把你的写作方法，变成可选能力。','导入自己的写作与去 AI 味 Skill，规则版本独立留存，只有主动选择才会执行。','import-skill','导入 Skill')+`<div class="notice">应用拥有独立的 Skill 库。这里不会自动读取 Codex 或其他工具中的 Skill，不执行上传文件中的脚本和命令。</div>`+(state.skills.length?`<div class="cards">${state.skills.map(s=>`<article class="card"><div class="card-header"><span class="stat-icon">${ico('skill')}</span>${tag(s.data.enabled?'已启用':'已停用',s.data.enabled?'green':'gray')}</div><h3>${esc(s.data.title)}</h3><p>${esc(s.data.description)}</p><div class="inline">${tag(({writing:'写作规则',humanize:'去 AI 味',editing:'编辑规则',review:'审阅规则',research:'对标研究',breakdown:'文章拆解',planning:'创作规划',post_review:'发布后复盘'}[s.data.skill_type]||s.data.skill_type))}${tag(s.data.platform==='all'?'通用':platform(s.data.platform),'gray')}${tag('v'+s.data.version,'gray')}</div><div class="card-footer">${btn('查看规则与版本','skill-detail',`data-id="${s.id}"`,'ghost small')}${btn(s.data.enabled?'停用':'启用','toggle-skill',`data-id="${s.id}"`,'small')}</div></article>`).join('')}</div>`:empty('你的 Skill 库还是空的','导入 SKILL.md、.md 或仅包含文本参考文件的标准 ZIP 包。','import-skill','导入第一个 Skill','skill'))};
pages.settings=async()=>{const logs=await api('audit'+(state.accountId?scope():''));return title('安心创作，也照顾好资产。','备份、恢复与审计，保留内容的每一次重要变化。')+`<div class="split"><section class="panel"><div class="panel-head"><h2>数据备份</h2>${ico('shield')}</div><p class="subtitle">导出账号、选题、研究、内容修订、发布记录、指标与运行日志。备份不包含 API 密钥。</p><div class="inline" style="margin:20px 0">${btn(ico('download')+' 导出完整备份','backup','','primary')}${btn('从备份恢复','restore-backup')}</div><div class="notice warning">恢复仅支持空工作空间，避免覆盖现有稿件。API 密钥需要在恢复后重新配置。</div><p class="field-hint">桌面数据位于应用专属用户目录，升级应用不会主动删除数据。Mac 和 Windows 暂不自动同步，可通过备份迁移。</p></section><section class="panel"><div class="panel-head"><h2>关于 Media Studio</h2>${tag('0.2.0','gray')}</div><div class="list-row"><div class="list-main"><h4>精品创作 × 独立账号运营</h4><p>macOS / Windows · SQLite 本机存储</p></div></div><div class="list-row"><div class="list-main"><h4>默认 AI 直接写作</h4><p>可选写作 Skill · 后处理默认关闭</p></div></div><div class="list-row"><div class="list-main"><h4>真实生成与人工发布</h4><p>不自动采集、不自动向平台发文</p></div></div></section></div><section class="panel"><div class="panel-head"><h2>操作审计</h2><span class="caption">最近 200 条 · ${acc()?esc(acc().name):'当前工作空间'}</span></div>${logs.length?`<div class="table-wrap"><table><thead><tr><th>操作</th><th>对象 ID</th><th>时间</th></tr></thead><tbody>${logs.map(l=>`<tr><td>${esc(l.action)}</td><td class="caption">${esc(l.target_id)}</td><td class="muted">${fmt(l.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('尚无操作记录','后续的重要操作都会留在这里。','','','clock',true)}</section>`};
act.close=()=>$('#modal').close();act.retry=()=>render();act.menu=()=>$('.sidebar').classList.toggle('open');act.theme=()=>{document.body.classList.toggle('dark');localStorage.setItem('ms-theme',document.body.classList.contains('dark')?'dark':'light')};
for(const n of navs)act['nav-'+n[0]]=()=>go(n[0]);act['overview-current']=()=>{state.overviewAll=false;render()};act['overview-all']=()=>{state.overviewAll=true;render()};
