async function editAccount(a){const providers=await api('records/provider'),skills=await api('records/skill');modal(a?'编辑账号档案':'添加运营账号',`<div class="field-grid">${field('name','内部名称',a?.name||'')}${select('platform','运营平台',a?.platform||'wechat',[['wechat','微信公众号'],['xhs','小红书']])}${field('positioning','账号定位',a?.data.positioning||'','textarea','',true)}${field('audience','目标读者',a?.data.audience||'')}${field('pillars','内容支柱',a?.data.pillars||'')}${field('tone','语气与风格',a?.data.tone||'')}${field('length','长度偏好',a?.data.length||'')}${field('rules','创作规则 / 禁用词 / 来源要求',a?.data.rules||'','textarea','',true)}${select('default_provider_id','推荐模型',a?.data.default_provider_id||'',[['','未配置'],...providers.map(p=>[p.id,p.data.title])])}${select('recommended_skill','推荐写作 Skill',a?.data.recommended_skill||'',[['','不推荐'],...skills.filter(s=>s.data.skill_type==='writing').map(s=>[s.id,s.data.title])],'仅作为推荐，不改变新任务默认直接写作')}${a?select('status','账号状态',a.status,[['active','运营中'],['inactive','停用（保留历史）']]):''}</div>`,async f=>{await api('accounts'+(a?'/'+a.id:''),{method:a?'PATCH':'POST',body:{name:f.name,platform:f.platform,status:f.status||'active',data:{positioning:f.positioning,audience:f.audience,pillars:f.pillars,tone:f.tone,length:f.length,rules:f.rules,default_provider_id:f.default_provider_id,recommended_skill:f.recommended_skill}}});await refreshAccounts();await render();toast('账号档案已保存')})}
act['add-topic']=e=>{if(!acc())return act['add-account']();editTopic(null,e.dataset.status)};act['edit-topic']=e=>editTopic(state.items.find(t=>t.id===dataId(e)));
function editTopic(t,status='idea'){modal(t?'编辑选题':'收集一个选题',`<div class="notice">归属账号：${esc(acc().name)} · 仅用于该账号的内容策划</div>${field('title','选题标题',t?.data.title||'')}${field('description','观察 / 核心矛盾',t?.data.description||'','textarea')}${field('angle','差异化创作角度',t?.data.angle||'','textarea')}<div class="field-grid">${select('status','当前阶段',t?.data.status||status,['idea','research','ready','done'].map(s=>[s,statusName[s]]))}${select('priority','创作优先级',t?.data.priority||'normal',[['normal','常规'],['high','优先']])}${field('url','来源链接（可选）',t?.data.url||'','url')}${field('tags','关键词 / 内容支柱',t?.data.tags||'')}</div>${t?`<div class="inline">${btn('复制到其他账号','clone-topic',`data-id="${t.id}" type="button"`,'small')}${btn('删除选题','delete-topic',`data-id="${t.id}" type="button"`,'danger small')}</div>`:''}`,async f=>{const same=(await records('topic')).find(r=>r.id!==t?.id&&r.data.title.trim()===f.title.trim());if(same)throw new Error('当前账号已有同名选题，请修改标题以区分');await api('records/topic'+(t?'/'+t.id:'')+scope(),{method:t?'PATCH':'POST',body:{revision:t?.revision,data:{...f,post_id:t?.data.post_id||null}}});await render();toast('选题已保存')})}
act['topic-board']=()=>{state.view='board';render()};act['topic-list']=()=>{state.view='list';render()};
act['delete-topic']=async e=>{await api('records/topic/'+dataId(e)+scope(),{method:'DELETE'});$('#modal').close();await render();toast('选题已移入回收状态')};
act['clone-topic']=e=>cloneRecord('topic',dataId(e));async function cloneRecord(kind,rid){const targets=state.accounts.filter(a=>a.id!==state.accountId&&a.status==='active');if(!targets.length)return toast('请先添加另一个运营账号');modal('明确复制到另一个账号',`<div class="notice">复制会创建独立 ID。原账号的私有对标研究和素材不会跟随复制。</div>${select('target','目标账号',targets[0].id,targets.map(a=>[a.id,a.name+' / '+platform(a.platform)]))}`,async f=>{await api('records/'+kind+'/'+rid+'/clone'+scope(),{method:'POST',body:{target_account_id:f.target}});toast('已创建独立副本，目标账号可单独编辑')})}
act['topic-write']=async e=>{const t=await api('records/topic/'+dataId(e)+scope());await createContent(t.data.title,t.id)};
act['add-content']=()=>{if(!acc())return act['add-account']();modal('新建创作任务',`<div class="notice">当前账号：${esc(acc().name)}<br>新任务默认 AI 直接写作，去 AI 味关闭。</div>${field('title','文章标题 / 选题方向','')}${select('platform','目标平台',acc().platform,[['wechat','微信公众号'],['xhs','小红书']])}`,async f=>createContent(f.title,null,f.platform))};
async function createContent(title,topic=null,p){await flush();const c=await api('records/content'+scope(),{method:'POST',body:{data:{title,body:'',summary:'',topic_id:topic,platform:p||acc().platform,writing_skill_version_id:null,humanize_enabled:false,humanize_skill_version_id:null,provider_id:null,status:'draft'}}});state.studio=c;await go('studio',c.id)}
act['open-content']=async e=>{await flush();if(e.dataset.account&&e.dataset.account!==state.accountId){state.accountId=e.dataset.account;localStorage.setItem('ms-account',state.accountId)}await go('studio',dataId(e))};
act['library-active']=()=>{state.libraryDeleted=false;render()};act['library-trash']=()=>{state.libraryDeleted=true;render()};
act['delete-content']=async e=>{await api('records/content/'+dataId(e)+scope(),{method:'DELETE'});if(state.studio?.id===dataId(e))state.studio=null;await render();toast('稿件已移入回收站，历史修订仍然保留')};
act['recover-content']=async e=>{const c=state.contents.find(c=>c.id===dataId(e));await api('records/content/'+c.id+scope(),{method:'PATCH',body:{data:c.data,revision:c.revision,restore_deleted:true}});await render();toast('稿件已恢复')};
act['history-content']=e=>history(dataId(e));act['history-current']=async()=>{await flush();history(state.studio.id)};
async function history(cid){const c=await api('records/content/'+cid+scope()),revs=await api('records/content/'+cid+'/revisions'+scope());state.history={c,revs};modal('不可变修订历史',`<div class="notice">恢复会创建新的修订；旧版本保留。当前：v${c.revision}</div><div class="revision-list">${revs.map(r=>`<div class="list-row"><div class="list-main"><h4>v${r.revision} · ${esc(r.data.title)}</h4><p>${fmt(r.created_at)} · ${esc(r.source)}</p><details><summary class="caption">查看正文快照</summary><pre>${esc(r.data.body||'')}</pre></details></div>${r.revision!==c.revision?btn('恢复此版','restore-revision',`data-revision="${r.revision}" type="button"`,'small'):tag('当前版本','green')}</div>`).join('')}</div>`,null,true)}
act['restore-revision']=async e=>{const {c}=state.history;await api('records/content/'+c.id+'/restore'+scope(),{method:'POST',body:{revision:Number(e.dataset.revision),expected_revision:c.revision}});$('#modal').close();state.openId=c.id;await render();toast('已恢复为新的修订版本')};
act['add-benchmark']=()=>editBenchmark();act['edit-benchmark']=e=>editBenchmark(state.benchmarks.find(b=>b.id===dataId(e)));
function editBenchmark(b){modal(b?'编辑对标账号':'添加对标账号',`${field('title','公开账号名称',b?.data.title||'')}${field('url','公开主页链接',b?.data.url||'','url')}${field('rationale','为什么研究这个账号？',b?.data.rationale||'','textarea')}${field('positioning','细分定位 / 受众 / 选题特点',b?.data.positioning||'','textarea')}${select('priority','观察优先级',b?.data.priority||'normal',[['normal','持续观察'],['high','重点观察']])}`,async f=>{await api('records/benchmark'+(b?'/'+b.id:'')+scope(),{method:b?'PATCH':'POST',body:{data:f,revision:b?.revision}});await render();toast('对标资料已保存')})}
act['benchmark-detail']=async e=>showBenchmark(dataId(e));async function showBenchmark(bid){const b=state.benchmarks.find(x=>x.id===bid)||await api('records/benchmark/'+bid+scope()),posts=(await records('post')).filter(x=>x.data.benchmark_id===bid);state.detailBenchmark=b;state.detailPosts=posts;modal(b.data.title+' · 文章研究',`<div class="notice">${esc(b.data.rationale||'为当前账号独立记录研究笔记。')}</div>${btn('＋ 保存一篇对标文章','add-post',`data-benchmark="${bid}" type="button"`,'primary small')}<div style="margin-top:20px">${posts.length?posts.map(p=>`<div class="list-row"><div class="list-main"><h4>${esc(p.data.title)}</h4><p>${esc(p.data.summary||'')}</p></div>${btn('查看拆解','post-detail',`data-id="${p.id}" type="button"`,'small')}${btn('提炼选题','post-to-topic',`data-id="${p.id}" type="button"`,'small')}</div>`).join(''):empty('研究从一篇文章开始','记录链接、摘要、钩子和你观察到的表达方式。','','','research',true)}</div>`,null,true)}
act['add-post']=e=>editPost(null,e.dataset.benchmark);act['post-detail']=e=>editPost(state.detailPosts.find(p=>p.id===dataId(e)),state.detailBenchmark.id);
function editPost(p,bid){modal('对标文章拆解',`${field('title','文章标题',p?.data.title||'')}${field('url','公开文章来源链接',p?.data.url||'','url')}${field('summary','摘要（由你提供，不自动抓取）',p?.data.summary||'','textarea')}${field('hook','开头钩子 / 情绪与利益点',p?.data.hook||'','textarea')}${field('analysis','结构拆解 / 差异化启发',p?.data.analysis||'','textarea')}<div class="field-grid">${field('reads','可核查阅读数',p?.data.reads??'','number','未知请留空，0 表示确认是零')}${field('likes','可核查点赞数',p?.data.likes??'','number')}</div>${field('license','来源与许可说明',p?.data.license||'仅记录公开链接与人工研究摘要')}`,async f=>{await api('records/post'+(p?'/'+p.id:'')+scope(),{method:p?'PATCH':'POST',body:{revision:p?.revision,data:{...f,benchmark_id:bid}}});await render();toast('研究笔记已保存')},true)}
act['post-to-topic']=async e=>{const p=state.detailPosts.find(p=>p.id===dataId(e));const t=await api('records/topic'+scope(),{method:'POST',body:{data:{title:p.data.title,description:p.data.summary,angle:'',post_id:p.id,status:'idea',priority:'normal'}}});$('#modal').close();await go('topics');toast('已提炼为当前账号的新选题，来源关系已保留')};
function markDirty(){state.dirty=true;state.saveError=null;if($('#save-status'))$('#save-status').textContent='待保存…';clearTimeout(state.timer);state.timer=setTimeout(()=>flush().catch(e=>toast(e.message)),1200)}
async function flush(){clearTimeout(state.timer);if(state.saving)await state.saving;if(state.saveError)throw state.saveError;if(!state.dirty||!state.studio)return;const c=state.studio,aid=c.account_id;const snapshot={...c.data};state.dirty=false;state.saving=(async()=>{try{const saved=await api('records/content/'+c.id+'?accountId='+aid,{method:'PATCH',body:{data:snapshot,revision:c.revision}});if(state.studio?.id===c.id){state.studio.revision=saved.revision;state.studio.updated_at=saved.updated_at;if($('#save-status'))$('#save-status').textContent=state.dirty?'待保存…':'已保存 · v'+saved.revision;sessionStorage.removeItem('ms-recovery-'+c.id)}}catch(e){state.dirty=true;state.saveError=e;sessionStorage.setItem('ms-recovery-'+c.id,JSON.stringify(snapshot));if($('#save-status'))$('#save-status').textContent='未保存 · '+e.message;throw e}finally{state.saving=null}})();await state.saving;if(state.dirty&&!state.saveError)await flush()}
function bindPage(){if($('#list-search')){$('#list-search').onchange=e=>{state.filter=e.target.value;render()}}if(state.page==='studio'&&state.studio){for(const [sel,key]of [['#editor-title','title'],['#editor-summary','summary'],['#editor-body','body']])$(sel).oninput=e=>{state.studio.data[key]=e.target.value;sessionStorage.setItem('ms-recovery-'+state.studio.id,JSON.stringify(state.studio.data));if($('#word-count'))$('#word-count').textContent=state.studio.data.body.replace(/\s/g,'').length+' 字';markDirty()};$('#f-current-content').onchange=e=>go('studio',e.target.value);$('#f-studio-provider').onchange=e=>{state.studio.data.provider_id=e.target.value||null;markDirty()};document.querySelectorAll('[name=writing-mode]').forEach(r=>r.onchange=e=>{state.studio.data.writing_skill_version_id=e.target.value||null;markDirty()});$('#humanize-enabled').onchange=e=>{state.studio.data.humanize_enabled=e.target.checked;markDirty()};$('#f-humanize-skill').onchange=e=>{state.studio.data.humanize_skill_version_id=e.target.value||null;markDirty()};const recovery=sessionStorage.getItem('ms-recovery-'+state.studio.id);if(recovery){toast('发现本机未保存内容，可在版本冲突时恢复');const node=document.createElement('button');node.textContent='载入本机未保存内容';node.className='small';node.onclick=()=>{const d=JSON.parse(recovery);Object.assign(state.studio.data,d);$('#editor-title').value=d.title;$('#editor-body').value=d.body;$('#editor-summary').value=d.summary||'';state.saveError=null;markDirty()};$('.editor-toolbar').append(node)}}if($('#f-layout-content'))$('#f-layout-content').onchange=e=>{state.layoutId=e.target.value;render()};if($('#f-layout-style'))$('#f-layout-style').onchange=e=>{state.layoutStyle=e.target.value;render()}}
for(const action of ['draft','outline','titles','rewrite','humanize'])act['ai-'+action]=()=>runAI(action);
async function runAI(action){if(!state.studio)return;await flush();const c=state.studio,aid=state.accountId,feedback=$('#ai-feedback'),instruction=$('#ai-instruction').value;feedback.textContent='正在调用模型…原稿已保存，你可以继续编辑。';const refreshRuns=setInterval(async()=>{try{if(state.accountId!==aid||state.studio?.id!==c.id)return;state.runs=await api('runs'+scope());if($('#candidates'))$('#candidates').innerHTML=state.runs.filter(r=>r.content_id===c.id).slice(0,3).map(runCard).join('')}catch{}},3000);document.querySelectorAll('.ai-actions button').forEach(b=>b.disabled=true);try{const r=await api('runs?accountId='+aid,{method:'POST',body:{content_id:c.id,source_revision:c.revision,action,instruction,provider_id:c.data.provider_id||acc().data.default_provider_id}});if(state.accountId!==aid||state.studio?.id!==c.id)return;toast(r.status==='cancelled'?'任务已取消，原稿保留':r.data?.partial?'后处理失败，初稿已保留，请查看候选':'候选已生成，请比较后采纳');state.runs=await api('runs'+scope());$('#candidates').innerHTML=state.runs.filter(r=>r.content_id===c.id).slice(0,3).map(runCard).join('');feedback.textContent='运行结束。候选不会自动覆盖正文。'}catch(e){toast(e.message);if(document.contains(feedback))feedback.textContent=e.message;if(state.accountId===aid){state.runs=await api('runs'+scope());if($('#candidates'))$('#candidates').innerHTML=state.runs.filter(r=>r.content_id===c.id).slice(0,3).map(runCard).join('')}}finally{clearInterval(refreshRuns);document.querySelectorAll('.ai-actions button').forEach(b=>b.disabled=false)}}
act['cancel-run']=async e=>{await api('runs/'+dataId(e)+'/cancel'+scope(),{method:'POST',body:{}});toast('已取消采纳，供应商可能仍计入已发出的请求费用');await render()};
act['copy-run']=e=>navigator.clipboard.writeText(state.runs.find(r=>r.id===dataId(e)).data.output).then(()=>toast('候选已复制'));
act['compare-run']=async e=>{await flush();const r=state.runs.find(r=>r.id===dataId(e));state.compareRun=r;modal('比较候选与当前正文',`<div class="notice">原稿基于 v${r.source_revision}，当前 v${state.studio.revision}。采纳会创建新修订。</div><div class="split"><div><label>当前正文</label><div class="candidate old">${esc(state.studio.data.body||'（空白稿件）')}</div></div><div><label>${r.data.humanize_skill_version_id?'后处理候选':'AI 初稿候选'}</label><div class="candidate">${esc(r.data.output)}</div></div></div>${r.data.humanize_skill_version_id?`<details><summary class="caption">查看后处理前的初稿</summary><div class="candidate">${esc(r.data.draft)}</div>${btn('仅采纳初稿','accept-draft','type="button"','small')}</details>`:''}<p class="field-hint">修改过原稿时拒绝覆盖，可复制候选后自行合并。</p>`,async()=>acceptRun('output'),true)};
async function acceptRun(candidate){const r=state.compareRun;state.studio=await api('runs/'+r.id+'/accept'+scope(),{method:'POST',body:{expected_revision:state.studio.revision,candidate}});state.openId=state.studio.id;await render();toast('候选已采纳，原稿保留在版本历史中')};act['accept-draft']=async()=>{await acceptRun('draft');$('#modal').close()};
act['retry-save']=async()=>{state.saveError=null;await flush();toast('稿件已保存')};
