act['derive-content']=async()=>{const c=state.contents.find(c=>c.id===state.layoutId),p=c.data.platform==='wechat'?'xhs':'wechat';const r=await api('records/content'+scope(),{method:'POST',body:{data:{title:c.data.title+' · '+platform(p)+'版',body:'',summary:'由《'+c.data.title+'》派生，请按目标平台重新创作。',source_content_id:c.id,platform:p,topic_id:c.data.topic_id,writing_skill_version_id:null,humanize_enabled:false,humanize_skill_version_id:null,provider_id:c.data.provider_id||null}}});toast('已创建独立派生稿，请针对目标平台重新编辑或生成');await go('studio',r.id)};
function download(data,name,type='text/plain;charset=utf-8'){const a=document.createElement('a'),url=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),20000)}
const fileName=s=>(s||'未命名').replace(/[\\/:*?"<>|]/g,'_').slice(0,80),layoutContent=()=>state.contents.find(c=>c.id===state.layoutId);
act['export-md']=()=>{const c=layoutContent();download('# '+c.data.title+'\n\n'+c.data.body,fileName(c.data.title)+'.md','text/markdown;charset=utf-8');toast('Markdown 已导出')};
act['export-html']=()=>{const c=layoutContent(),color={lavender:'#7662d7',sage:'#578b74',ink:'#343e4e'}[state.layoutStyle||'lavender'];let html=mdHTML(c.data.body).replace(/<p>/g,'<p style="margin:0 0 20px;font-size:16px;line-height:1.9;letter-spacing:0.4px">').replace(/<h2>/g,'<h2 style="font-size:20px;margin:28px 0 18px;color:'+color+'">').replace(/<blockquote>/g,'<blockquote style="border-left:3px solid '+color+';padding:5px 16px;color:#888">');download('<!doctype html><html lang="zh-CN"><meta charset="UTF-8"><title>'+esc(c.data.title)+'</title><body><article style="max-width:640px;margin:auto;padding:24px;color:#333;font-family:system-ui"><h1 style="font-size:25px;line-height:1.5">'+esc(c.data.title)+'</h1>'+html+'</article></body></html>',fileName(c.data.title)+'.html','text/html;charset=utf-8');toast('公众号兼容 HTML 已导出')};
// ZIP store writer: native, no runtime dependencies. Files are generated in order.
function bytesBase64(bytes){let s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(s)}
const crc32=b=>{let crc=-1;for(const c of b){crc^=c;for(let k=0;k<8;k++)crc=(crc>>>1)^((crc&1)?0xedb88320:0)}return(crc^-1)>>>0};
function zipStore(files){const locals=[],central=[];let offset=0;for(const f of files){const name=new TextEncoder().encode(f.name),data=f.data,crc=crc32(data),h=new Uint8Array(30+name.length),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);h.set(name,30);locals.push(h,data);const ch=new Uint8Array(46+name.length),cv=new DataView(ch.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint32(16,crc,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);ch.set(name,46);central.push(ch);offset+=h.length+data.length}const end=new Uint8Array(22),ev=new DataView(end.buffer),size=central.reduce((a,b)=>a+b.length,0);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,files.length,true);ev.setUint16(10,files.length,true);ev.setUint32(12,size,true);ev.setUint32(16,offset,true);return new Blob([...locals,...central,end],{type:'application/zip'})}
act['export-cards']=async()=>{const c=layoutContent(),raw=c.data.body||'',pages=[];for(let n=0;n<raw.length;n+=340)pages.push(raw.slice(n,n+340));if(!pages.length)pages.push('');if(pages.length>9)throw new Error('当前正文需要 '+pages.length+' 张卡片，超过首版九张上限，请先精简或拆分稿件');const colors={lavender:['#f2edf8','#4f3f70','#9b80c7'],sage:['#eef3ee','#3f594b','#7b9c84'],ink:['#f3f0eb','#343e4e','#788293']},[bg,ink,accent]=colors[state.layoutStyle||'lavender'],files=[];await document.fonts.ready;for(let i=0;i<pages.length;i++){const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1440;const ctx=canvas.getContext('2d');ctx.fillStyle=bg;ctx.fillRect(0,0,1080,1440);ctx.fillStyle=accent;ctx.fillRect(82,88,55,7);ctx.font='24px sans-serif';ctx.fillText(acc().name,82,150);ctx.fillStyle=ink;const wrap=(txt,size,x,y,max,lh)=>{ctx.font=size+'px sans-serif';let line='';for(const ch of txt){if(ch==='\n'||ctx.measureText(line+ch).width>max){ctx.fillText(line,x,y);y+=lh;line=ch==='\n'?'':ch}else line+=ch}if(line)ctx.fillText(line,x,y);return y+lh};let y=wrap(c.data.title,48,82,250,910,76);y+=35;wrap(pages[i].replace(/^#+\s*/gm,'').replace(/\*\*/g,''),30,82,y,910,56);ctx.fillStyle=accent;ctx.font='22px sans-serif';ctx.fillText(String(i+1).padStart(2,'0')+' / '+String(pages.length).padStart(2,'0'),82,1355);ctx.fillText('MEDIA STUDIO',775,1355);const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));files.push({name:String(i+1).padStart(2,'0')+'.png',data:new Uint8Array(await blob.arrayBuffer())})}files.push({name:'caption.md',data:new TextEncoder().encode('# '+c.data.title+'\n\n'+c.data.body+'\n\n发布前核对：账号、顺序、事实、版权与标签。')});download(zipStore(files),fileName(c.data.title)+'-图文素材.zip');toast('已导出 '+pages.length+' 张 PNG 与正文，请人工核对排版')};
const localDay=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
const localInput=d=>localDay(d)+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');
act['schedule-current']=()=>schedule(state.layoutId);act.schedule=()=>schedule();async function schedule(cid){const contents=await records('content');if(!contents.length)return toast('请先创建并保存一篇稿件');modal('创建发布排期',`<div class="notice">目标账号：${esc(acc().name)} · ${platform(acc().platform)}<br>创建后进入待审核，不会向任何平台发送。</div>${select('content_id','选择已保存稿件',cid||contents[0].id,contents.map(c=>[c.id,c.data.title+' / '+platform(c.data.platform)]))}${field('scheduled_at','计划发布时间',localInput(new Date(Date.now()+3600000)),'datetime-local')}`,async f=>{await api('jobs'+scope(),{method:'POST',body:{content_id:f.content_id,scheduled_at:new Date(f.scheduled_at).toISOString()}});await go('publishing');toast('排期已创建，等待审核具体稿件版本')})}
act['publish-calendar']=()=>{state.publishView='calendar';render()};act['publish-queue']=()=>{state.publishView='queue';render()};act['month-prev']=()=>{state.month=new Date(state.month.getFullYear(),state.month.getMonth()-1,1);render()};act['month-next']=()=>{state.month=new Date(state.month.getFullYear(),state.month.getMonth()+1,1);render()};
act['job-detail']=async e=>jobDetail(dataId(e));async function jobDetail(jid){const j=await api('records/job/'+jid+scope()),c=await api('records/content/'+j.data.content_id+scope());state.jobDetail={j,c};const stale=j.data.review_revision&&j.data.review_revision!==c.revision&&j.data.status!=='published';modal('发布任务 · '+j.data.title,`<div class="notice">账号：${esc(acc().name)} · ${platform(j.data.platform)}<br>状态：${statusName[j.data.status]} · 计划 ${fmt(j.data.scheduled_at)}<br>当前稿件 v${c.revision}，已审核版本 ${j.data.review_revision?'v'+j.data.review_revision:'尚未审核'}</div>${stale?'<div class="notice warning">稿件已修改，原审核失效，需要重新审核。</div>':''}<div class="candidate">${esc((j.data.status==='published'?j.data.snapshot?.body:c.data.body)||'')}</div>${j.data.url?`<p><a href="${esc(j.data.url)}" target="_blank" rel="noopener">查看实际发布作品 ↗</a></p>`:''}<div class="inline">${!['published','cancelled'].includes(j.data.status)?btn('审核当前版本','approve-job','type="button"','primary small'):''}${j.data.status==='approved'&&!stale?btn('进入人工发布','prepare-job','type="button"','primary small'):''}${j.data.status==='manual_pending'&&!stale?btn('回填链接，确认已发布','confirm-job','type="button"','primary small'):''}${!['published','cancelled'].includes(j.data.status)?btn('取消任务','cancel-job','type="button"','danger small'):''}${btn('查看稿件排版','job-layout','type="button"','small')}</div>`,null,true)}
async function jobAction(action,other={}){const {j,c}=state.jobDetail;await api('jobs/'+j.id+scope(),{method:'POST',body:{action,revision:c.revision,expected_revision:j.revision,...other}});$('#modal').close();await render();toast('发布任务已更新')}
