act['confirm-job']=()=>{const {j}=state.jobDetail;modal('确认已在平台发布',`<div class="notice warning">请核对：${esc(acc().name)} / ${platform(j.data.platform)} / ${esc(j.data.title)}。仅在已实际发布后确认。</div>${field('url','实际文章链接','','url')}${field('published_at','实际发布时间',localInput(new Date()),'datetime-local')}<label class="inline"><input name="confirmed" type="checkbox" required>已核对平台账号、文章内容与发布时间</label>`,async f=>jobAction('confirm',{url:f.url,published_at:new Date(f.published_at).toISOString(),confirm_account_id:state.accountId}))};
act['add-metric']=async()=>{const jobs=(await records('job')).filter(j=>j.data.status==='published');if(!jobs.length)return toast('请先完成一次真实发布并回填链接');modal('录入累计指标快照',`${select('job_id','已发布作品',jobs[0].id,jobs.map(j=>[j.id,j.data.title]))}${field('observed_at','实际采集时间',localInput(new Date()),'datetime-local')}<div class="field-grid">${['reads','likes','saves','comments','shares'].map((k,i)=>field(k,['累计阅读','累计点赞','累计收藏','累计评论','累计分享'][i],'','number','未知留空，确认是零才填 0')).join('')}</div>${field('note','口径 / 来源说明','','textarea')}`,async f=>{f.observed_at=new Date(f.observed_at).toISOString();await api('records/metric'+scope(),{method:'POST',body:{data:f}});await render();toast('指标已保存，汇总仅取最新累计快照')})};
act['csv-template']=()=>{download('job_id,observed_at,reads,likes,saves,comments,shares,note\n','metrics-template.csv','text/csv;charset=utf-8');toast('模板已导出；作品 ID 可从已发布记录或备份中获取')};
function parseCSV(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(cell);cell=''}else if(c==='\n'&&!quote){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell=''}else cell+=c}if(quote)throw new Error('CSV 引号未闭合');if(cell||row.length){row.push(cell.replace(/\r$/,''));rows.push(row)}return rows.filter(r=>r.some(c=>c.trim()))}
act['import-metrics']=()=>pickFile('.csv',async file=>{const rows=parseCSV((await file.text()).replace(/^\uFEFF/,'')),header=rows.shift();if(!header?.includes('job_id')||!header.includes('observed_at'))throw new Error('CSV 需要 job_id 和 observed_at 表头');const allowed=['job_id','observed_at','reads','likes','saves','comments','shares','note'];if(header.some(h=>!allowed.includes(h)))throw new Error('CSV 表头不在支持范围，请使用模板');const data=rows.map((r,index)=>{if(r.length!==header.length)throw new Error('第 '+(index+2)+' 行列数不匹配');return Object.fromEntries(header.map((k,i)=>[k,r[i]]))});modal('确认导入指标',`<div class="notice">目标账号：${esc(acc().name)}<br>文件：${esc(file.name)} · ${data.length} 行<br>按模板表头直接映射，空指标保持未知，重复批次会被拒绝。</div><div class="candidate">${esc(JSON.stringify(data.slice(0,5),null,2))}</div>`,async()=>{const result=await api('metrics-import'+scope(),{method:'POST',body:{rows:data}});await render();toast('已导入 '+result.count+' 行真实指标')})});
act['add-provider']=()=>editProvider();act['edit-provider']=e=>editProvider(state.providers.find(p=>p.id===dataId(e)));
async function editProvider(p){const st=p?await api('providers/'+p.id+'/status'):null;modal(p?'编辑模型配置':'添加真实模型接口',`<div class="notice">密钥在本机服务端 AES-GCM 加密保存。价格单位为所选币种 / 百万 Token，预算使用同一币种。</div><div class="field-grid">${field('title','配置名称',p?.data.title||'')}${select('protocol','调用协议',p?.data.protocol||'openai',[['openai','OpenAI Chat Completions 兼容'],['anthropic','Anthropic Messages']])}${field('base_url','API Base URL',p?.data.base_url||'https://api.deepseek.com/v1','url','填写带 /v1 等版本路径的 API 地址',true)}${field('model','模型 ID',p?.data.model||'')}${field('api_key',st?.mask?'API Key（'+st.mask+'，留空保留）':'API Key','','password')}${select('currency','计价币种',p?.data.currency||'CNY',[['CNY','CNY 人民币'],['USD','USD 美元']])}${field('max_tokens','输出 Token 上限',p?.data.max_tokens||3000,'number')}${field('input_price','输入价 / 百万 Token',p?.data.input_price??'','number')}${field('output_price','输出价 / 百万 Token',p?.data.output_price??'','number')}${field('per_run_limit','单次预算',p?.data.per_run_limit??1,'number')}${field('daily_limit','账号每日预算',p?.data.daily_limit??10,'number')}${field('monthly_limit','账号每月预算',p?.data.monthly_limit??100,'number')}${select('enabled','配置状态',p?.data.enabled===false?'false':'true',[['true','已启用'],['false','停用']])}</div><p class="field-hint">支持域名：api.openai.com、api.anthropic.com、api.deepseek.com、dashscope.aliyuncs.com、dashscope-intl.aliyuncs.com、openrouter.ai、api.siliconflow.cn / .com、api.mistral.ai、api.x.ai、api.together.xyz、api.fireworks.ai。为防止 SSRF，首版拒绝任意自定义域名。</p>`,async f=>{f.enabled=f.enabled==='true';await api('records/provider'+(p?'/'+p.id:'')+(state.accountId?scope():''),{method:p?'PATCH':'POST',body:{data:f,revision:p?.revision}});await render();toast('模型配置已保存，请运行真实连接测试')},true)}
act['test-provider']=async e=>{e.disabled=true;e.textContent='测试中…';try{const r=await api('providers/'+dataId(e)+'/test',{method:'POST',body:{}});toast('连接成功 · '+r.latency_ms+' ms · '+(r.usage.input_tokens+r.usage.output_tokens)+' tokens')}finally{e.disabled=false;e.textContent='连接测试'}};
act['model-catalog']=async e=>{toast('正在同步供应商模型目录…');const r=await api('providers/'+dataId(e)+'/models',{method:'POST',body:{}});modal('供应商模型目录',`<p class="subtitle">以下 ID 来自供应商真实响应。复制所需 ID 后在模型配置中保存。</p><div class="candidate">${r.models.map(m=>esc(m.id)).join('\n')||'未返回模型，请手动填写 ID。'}</div>`,null)};
act['save-default-provider']=async()=>{const a=acc();await api('accounts/'+a.id,{method:'PATCH',body:{name:a.name,status:a.status,data:{default_provider_id:$('#f-default-provider').value||null}}});await refreshAccounts();toast('当前账号默认模型已保存')};
function pickFile(accept,callback){const input=document.createElement('input');input.type='file';input.accept=accept;input.style.display='none';document.body.append(input);input.addEventListener('cancel',()=>input.remove(),{once:true});input.onchange=async()=>{if(input.files[0])try{await callback(input.files[0])}catch(e){toast(e.message)}finally{input.remove()}};input.click()}
act['import-skill']=()=>pickFile('.md,.zip',async file=>{if(file.size>1048576)throw new Error('Skill 文件最大 1 MB');const isZip=file.name.toLowerCase().endsWith('.zip');const d=isZip?{zip_base64:bytesBase64(new Uint8Array(await file.arrayBuffer()))}:{markdown:await file.text()};modal('预览并导入 Skill',`<div class="notice">文件：${esc(file.name)} · 不执行任何脚本。<br>需要 name、display_name、description、version 四个纯文本元数据。</div><div class="field-grid">${select('skill_type','Skill 类型','writing',[['writing','写作规则'],['humanize','去 AI 味后处理'],['editing','编辑规则'],['review','审阅规则']])}${select('platform','适用平台','all',[['all','通用'],['wechat','微信公众号'],['xhs','小红书']])}</div>${!isZip?`<div class="candidate">${esc(d.markdown)}</div>`:'<p class="subtitle">ZIP 将在本机服务端校验路径、文件类型、压缩比和引用完整性。</p>'}`,async f=>{await api('records/skill'+(state.accountId?scope():''),{method:'POST',body:{data:{...d,...f,enabled:true,source:file.name}}});await render();toast('Skill 已通过校验并导入')},true)});
act['toggle-skill']=async e=>{const s=state.skills.find(s=>s.id===dataId(e));await api('records/skill/'+s.id+(state.accountId?scope():''),{method:'PATCH',body:{revision:s.revision,data:{enabled:!s.data.enabled}}});await render();toast('Skill 状态已更新；历史规则快照保留')};
act['skill-detail']=async e=>{const s=state.skills.find(s=>s.id===dataId(e)),revs=await api('records/skill/'+s.id+'/revisions'+(state.accountId?scope():''));state.skillDetail=s;modal(s.data.title+' · v'+s.data.version,`<div class="notice">SHA-256：${esc(s.data.hash)}<br>版本 ID：${esc(s.data.version_id)}</div><label>不可变规则快照</label><div class="candidate">${esc(s.data.markdown)}</div>${Object.keys(s.data.references||{}).length?`<label>包内参考文件</label><div class="candidate">${esc(Object.keys(s.data.references).join('\n'))}</div>`:''}<div class="inline">${btn('编辑为新版本','new-skill-version','type="button"','primary small')}${btn('在当前创作中测试','test-skill','type="button"','small')}</div><h4 style="font-size:12px">版本时间线</h4>${revs.map(r=>`<div class="list-row"><div class="list-main"><h4>v${esc(r.data.version)} · ${fmt(r.created_at)}</h4><p>${esc(r.data.version_id)}</p></div>${btn('查看规则','preview-skill-rev',`type="button" data-id="${s.id}" data-revision="${r.revision}"`,'small')}</div>`).join('')}`,null,true)};
act['new-skill-version']=()=>{const s=state.skillDetail;modal('创建新的 Skill 版本',`${field('markdown','完整 SKILL.md（请递增 version）',s.data.markdown,'textarea')}`,async f=>{if(f.markdown===s.data.markdown)throw new Error('规则未变化');await api('records/skill/'+s.id+(state.accountId?scope():''),{method:'PATCH',body:{revision:s.revision,data:{markdown:f.markdown}}});await render();toast('新版本已保存，旧稿运行快照不受影响')},true)};
act['preview-skill-rev']=async e=>{const revs=await api('records/skill/'+dataId(e)+'/revisions'+(state.accountId?scope():'')),r=revs.find(r=>r.revision===Number(e.dataset.revision));modal('历史 Skill v'+r.data.version,`<div class="candidate">${esc(r.data.markdown)}</div>`,null,true)};
act['test-skill']=async()=>{const s=state.skillDetail;if(!state.studio||state.studio.account_id!==state.accountId){toast('请先为当前账号新建一篇稿件，再在创作页选择 Skill 运行真实测试');$('#modal').close();return go('studio')}await flush();if(s.data.skill_type==='humanize'){state.studio.data.humanize_skill_version_id=s.data.version_id;state.studio.data.humanize_enabled=true}else state.studio.data.writing_skill_version_id=s.data.version_id;markDirty();await flush();$('#modal').close();await go('studio',state.studio.id);toast('已显式选择该 Skill。点击生成会真实调用模型并记录成本')};
act.assets=async()=>{const assets=await records('asset');state.assets=assets;modal('当前账号素材库',`<div class="notice">所有素材独立归属于 ${esc(acc().name)}。添加来源和许可信息后，在创作中主动选择引用。</div>${btn('添加文本素材','add-asset','type="button"','primary small')}${assets.length?assets.map(a=>`<div class="list-row"><div class="list-main"><h4>${esc(a.data.title)}</h4><p>${esc(a.data.license||'许可未填写')}</p></div>${btn('查看与编辑','edit-asset',`data-id="${a.id}" type="button"`,'small')}</div>`).join(''):empty('还没有素材','记录可授权使用的资料、事实出处或自己的笔记。','','','file',true)}`,null,true)};
act['add-asset']=()=>editAsset();act['edit-asset']=e=>editAsset(state.assets.find(a=>a.id===dataId(e)));function editAsset(a){modal('文本素材与出处',`${field('title','素材标题',a?.data.title||'')}${field('body','资料 / 可引用事实',a?.data.body||'','textarea')}${field('url','出处链接',a?.data.url||'','url')}${field('license','版权许可 / 摘录范围',a?.data.license||'')}`,async f=>{await api('records/asset'+(a?'/'+a.id:'')+scope(),{method:a?'PATCH':'POST',body:{data:f,revision:a?.revision}});toast('素材已保存');await render()})}
act['select-assets']=async()=>{const assets=await records('asset');modal('选择本次创作可引用的素材',`<div class="notice">只列出当前账号的素材。勾选后才会加入模型输入。</div>${assets.length?assets.map(a=>`<label class="radio-card"><input type="checkbox" name="asset" value="${a.id}" ${(state.studio.data.asset_ids||[]).includes(a.id)?'checked':''}><span>${esc(a.data.title)}<small>${esc(a.data.license||'许可尚未填写')}</small></span></label>`).join(''):empty('暂无素材','可在内容中心的素材库添加。','','','file',true)}`,async(f,form)=>{state.studio.data.asset_ids=new FormData(form).getAll('asset');markDirty();await flush();toast('本次素材引用已保存')})};
act.backup=async()=>{await flush();const b=await api('backup');download(JSON.stringify(b,null,2),'Media-Studio-备份-'+localDay(new Date())+'.json','application/json');toast('备份已导出，不含 API 密钥')};
act['restore-backup']=()=>pickFile('.json',async file=>{const b=JSON.parse(await file.text());modal('恢复备份到空工作空间',`<div class="notice warning">文件：${esc(file.name)}<br>账号 ${b.accounts?.length||0} 个，数据 ${b.records?.length||0} 条。<br>仅可恢复到空工作空间，完成后需重新配置 API Key。</div>`,async()=>{await api('backup',{method:'POST',body:b});await refreshAccounts();await render();toast('备份已恢复')})});
act.search=()=>{if(!acc())return toast('请先添加账号');modal('搜索当前账号的内容',`${field('search','搜索标题、正文或研究笔记','','text')}<div id="search-results"></div>`,null);$('#f-search').oninput=async e=>{const q=e.target.value.trim().toLowerCase();if(!q){$('#search-results').innerHTML='';return}const groups=await Promise.all(['topic','content','post'].map(async kind=>(await records(kind)).filter(r=>JSON.stringify(r.data).toLowerCase().includes(q)).slice(0,10).map(r=>({...r,kind}))));if(!$('#search-results'))return;$('#search-results').innerHTML=groups.flat().map(r=>`<div class="list-row"><div class="list-main"><h4>${esc(r.data.title)}</h4><p>${{topic:'选题',content:'稿件',post:'研究笔记'}[r.kind]}</p></div>${r.kind==='content'?btn('打开','search-open',`type="button" data-id="${r.id}"`,'small'):''}</div>`).join('')||'<p class="subtitle">当前账号没有匹配结果。</p>'}};
act['search-open']=e=>{$('#modal').close();go('studio',dataId(e))};
document.addEventListener('click',async e=>{const el=e.target.closest('[data-act],[data-nav]');if(!el)return;if(el.tagName==='BUTTON'&&el.closest('form')&&el.type==='submit'&&!el.hasAttribute('type'))e.preventDefault();try{if(el.dataset.nav)await go(el.dataset.nav);else if(act[el.dataset.act])await act[el.dataset.act](el)}catch(err){toast(err.message)}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();act.search()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();flush().then(()=>toast('稿件已保存')).catch(e=>toast(e.message))}});
window.addEventListener('beforeunload',e=>{if(state.dirty||state.saving){e.preventDefault();e.returnValue='稿件尚未保存';}});
window.addEventListener('hashchange',async()=>{const [page,cid]=location.hash.slice(1).split('/');if(page&&pages[page]&&page!==state.page){await flush();state.page=page;state.openId=cid;render()}});
if(localStorage.getItem('ms-theme')==='dark')document.body.classList.add('dark');
(async()=>{try{await refreshAccounts();const [page,cid]=location.hash.slice(1).split('/');if(pages[page])state.page=page;if(cid)state.openId=cid;await render()}catch(e){$('#app').innerHTML=empty('无法打开工作台',e.message)}})();
